     environment: pulumi.Input<"dev" | "prod">;
     region: pulumi.Input<string>;
     vpcId?: pulumi.Input<string>;
     subnetIds?: pulumi.Input<string[]>;
     kmsKeyId?: pulumi.Input<string>;
     dbPassword: pulumi.Input<string>;
