     readonly rds: aws.rds.Instance;
     readonly iamRole: aws.iam.Role;
     readonly dbConnectionSecret: pulumi.Output<string>;

     constructor(name: string, args: AppInfraArgs, opts?: pulumi.ComponentResourceOptions) {
       super("my:infrastructure:AppInfra", name, {}, opts);

       const env = pulumi.getStack(); // or use args.environment

       // S3 Bucket
