         versioning: { enabled: true },
         serverSideEncryptionConfiguration: {
           rule: {
             applyServerSideEncryptionByDefault: {
               sseAlgorithm: args.kmsKeyId ? "aws:kms" : "AES256",
               kmsMasterKeyId: args.kmsKeyId,
             },
           },
         },
       }, { parent: this });

       new aws.s3.BucketPublicAccessBlock(`${name}-public-access-block`, {
         bucket: this.bucket.id,
         blockPublicAcls: true,
         blockPublicPolicy: true,
         ignorePublicAcls: true,
         restrictPublicBuckets: true,
       }, { parent: this });

       // RDS
       const rdsConfig = this.getRdsConfig(args);
       this.rds = new aws.rds.Instance(`${name}-db`, {
         engine: "postgres",
         engineVersion: "15.4",
         instanceClass: rdsConfig.instanceClass,
         allocatedStorage: rdsConfig.storage,
         dbSubnetGroupName: args.subnetIds ? new aws.rds.SubnetGroup(`${name}-subnet`, { subnetIds: args.subnetIds }, { parent: this }).name : undefined,
         vpcSecurityGroupIds: args.vpcId ? [this.createDefaultSecurityGroup(args.vpcId)] : undefined,
         publiclyAccessible: false,
         deletionProtection: true,
         backupRetentionPeriod: rdsConfig.backupRetention,
         multiAz: rdsConfig.multiAz,
         storageEncrypted: rdsConfig.storageEncrypted,
         kmsKeyId: args.kmsKeyId,
         username: "admin",
         password: args.dbPassword,
         skipFinalSnapshot: true,
       }, { parent: this });

       // IAM Role
       const trustPolicy = this.getIamTrustPolicy(args.environment);
       this.iamRole = new aws.iam.Role(`${name}-service-role`, {
         assumeRolePolicy: trustPolicy,
         inlinePolicies: [{ name: "service-access", policy: this.getIamPolicy(args.environment) }],
       }, { parent: this });

       // DB Connection Secret
       this.dbConnectionSecret = pulumi.interpolate`postgresql://${this.rds.username}:${args.dbPassword}@${this.rds.endpoint}/appdb`.apply(s => pulumi.secret(s));

       this.registerOutputs({
         bucket: this.bucket,
         rds: this.rds,
         iamRole: this.iamRole,
         dbConnectionSecret: this.dbConnectionSecret,
       });
     }

     private getRdsConfig(args: AppInfraArgs): { instanceClass: string; storage: number; backupRetention: number; multiAz: boolean; storageEncrypted: boolean } {
       const isProd = pulumi.output(args.environment).apply(e => e === "prod");
       return {
         instanceClass: pulumi.output(isProd).apply(p => p ? "db.t3.medium" : "db.t3.micro"),
         storage: 20,
         backupRetention: 7,
         multiAz: pulumi.output(isProd),
         storageEncrypted: pulumi.output(isProd),
       };
     }

     private getIamTrustPolicy(env: pulumi.Input<"dev" | "prod">): string {
       return pulumi.output(env).apply(e => {
         if (e === "prod") {
           return JSON.stringify({
             Version: "2012-10-17",
             Statement: [{
               Effect: "Allow",
               Principal: { Federated: "arn:aws:iam::<ACCOUNT_ID>:oidc-provider/oidc.eks.<REGION>.amazonaws.com/id/<CLUSTER_ID>" },
               Action: "sts:AssumeRoleWithWebIdentity",
               Condition: { StringEquals: { "oidc.eks.<REGION>.amazonaws.com/id/<CLUSTER_ID>:sub": "system:serviceaccount:<NS>:<SA>" } }
             }]
           });
         }
         return JSON.stringify({
           Version: "2012-10-17",
           Statement: [{ Effect: "Allow", Principal: { AWS: "arn:aws:iam::<ACCOUNT_ID>:user/dev-service-account" }, Action: "sts:AssumeRole" }]
         });
       });
     }

     private getIamPolicy(env: pulumi.Input<"dev" | "prod">): string {
       return pulumi.output(env).apply(e => {
         // Least privilege: specific S3 and RDS actions
         const s3Actions = ["s3:GetObject", "s3:PutObject", "s3:ListBucket"];
         const actions = [...s3Actions, "rds-db:connect"];
         const resources = ["arn:aws:s3:::*-app-assets", "arn:aws:s3:::*-app-assets/*"];
         return JSON.stringify({
           Version: "2012-10-17",
           Statement: [{
             Effect: "Allow",
             Action: s3Actions,
             Resource: resources
           }, {
             Effect: "Allow",
             Action: "rds-db:connect",
             Resource: "arn:aws:rds-db:*:*:dbinstance/*" // Simplified for component
           }]
         });
       });
     }
   }
   ```

